// features/lifecycle.feature: A re-uploaded document is the one that gets reviewed
import { expect, expectStatus, test } from "../../fixtures";
import type { Document, Vendor } from "../../fixtures";

interface QueueItem {
  vendor_id: string;
  extractions: { kind: string; document_id: string; fields: Record<string, { value: string | null; confidence: number }> }[];
}

test("a re-uploaded w9 is the one that gets reviewed", { tag: "@LIF-01" }, async ({ factory, apiAs }) => {
  // Arrange: a draft vendor with extracted insurance certificate and contract
  const member = await apiAs("member");
  const vendor = await factory.vendor();
  await factory.upload(vendor.id, "insurance_certificate");
  await factory.upload(vendor.id, "contract");

  // Arrange: first w9, "First Name LLC", extracted
  const first = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9-first.txt",
          mimeType: "text/plain",
          buffer: Buffer.from("Legal Name: First Name LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n"),
        },
      },
    }),
    201,
  );
  await expect
    .poll(async () => (await expectStatus<Document>(await member.get(`/api/documents/${first.id}`), 200)).status, {
      message: "first w9 is extracted",
      timeout: 30_000,
    })
    .toBe("extracted");

  // Arrange: second w9, "Second Name LLC", extracted
  const second = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9-second.txt",
          mimeType: "text/plain",
          buffer: Buffer.from("Legal Name: Second Name LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n"),
        },
      },
    }),
    201,
  );
  await expect
    .poll(
      async () =>
        (await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200))
          .map((d) => d.status)
          .sort(),
      { message: "all four uploads are extracted", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted", "extracted"]);

  // Act: submit, and a reviewer opens the review queue
  await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const reviewer = await apiAs("reviewer");
  const queue = await expectStatus<QueueItem[]>(await reviewer.get("/api/review-queue"), 200);

  // Assert: the queue's w9 extraction shows the second upload's legal name
  const item = queue.find((q) => q.vendor_id === vendor.id);
  expect(item, `vendor ${vendor.id} is in the review queue`).toBeDefined();
  const w9Extractions = (item?.extractions ?? []).filter((e) => e.kind === "w9");
  expect(w9Extractions, "the queue holds one w9 extraction").toHaveLength(1);
  expect(w9Extractions[0]?.fields.legal_name?.value).toBe("Second Name LLC");

  // Assert: the documents list keeps both w9 uploads, oldest first
  const documents = await expectStatus<Document[]>(await reviewer.get(`/api/vendors/${vendor.id}/documents`), 200);
  expect(documents.filter((d) => d.kind === "w9").map((d) => d.id)).toEqual([first.id, second.id]);
});
